<?php declare(strict_types=1);namespace App\Controllers;use App\Core\Controller;final class PageController extends Controller{public function home():void{$this->view('pages.home',['title'=>'AI Powered SEO, GEO & Content Intelligence Platform']);}public function about():void{$this->view('pages.simple',['title'=>'About','body'=>'WEBTRIXY AI helps teams evaluate SEO, GEO visibility, originality, readability, and publish readiness from one secure dashboard.']);}public function pricing():void{$this->view('pages.pricing',['title'=>'Pricing']);}public function blog():void{$this->view('pages.simple',['title'=>'Blog','body'=>'Actionable research and product updates for search, AI visibility, and content operations.']);}public function contact():void{$this->view('pages.contact',['title'=>'Contact']);}public function contactStore():void{\App\Core\Security::verify();$name=$this->input('name');$email=filter_var($this->input('email'),FILTER_VALIDATE_EMAIL);$message=$this->input('message');if(!$name||!$email||mb_strlen($message)<10){$this->view('pages.contact',['title'=>'Contact','error'=>'Enter your name, valid email, and a message of at least 10 characters.']);return;}$this->db->execute('insert into contacts(name,email,message) values(?,?,?)',[$name,$email,$message]);$this->view('pages.contact',['title'=>'Contact','success'=>'Your message has been saved. Our team will respond shortly.']);}public function policy():void{$this->view('pages.simple',['title'=>'Privacy Policy','body'=>'We collect account, usage, billing readiness, and security data required to operate the platform. Data is protected with encryption-aware transport, access controls, audit logs, and retention policies.']);}public function terms():void{$this->view('pages.simple',['title'=>'Terms','body'=>'Use WEBTRIXY AI lawfully, protect credentials, and review generated recommendations before publication.']);}public function api():void{$this->view('pages.simple',['title'=>'API Docs','body'=>'Authenticated API clients can submit content to /tool/run with CSRF/session protection in the web app and API keys for server integrations.']);}}
